398	// parseRegistryVersion accepts exactly the integer literal of FormatVersion.
399	// Other integers report an unsupported version; anything else (strings,
400	// fractions, exponents, booleans, null, arrays, objects) is a type error.
401	func parseRegistryVersion(raw json.RawMessage) (int, error) {
402		token := string(bytes.TrimSpace(raw))
403		if isJSONInteger(token) {
404			if token == strconv.Itoa(FormatVersion) {
405				return FormatVersion, nil
406			}
407			return 0, fmt.Errorf("unsupported registry version: got %s, want %d", token, FormatVersion)
408		}
409		return 0, &FormatError{Field: "version", Reason: fmt.Sprintf("must be the integer %d, not %s", FormatVersion, token)}
410	}
411	
412	// parseRegistryRecord validates one batches element: a JSON object with
413	// exactly the four required lowercase fields, text fields as JSON strings
414	// and quantity as a strict JSON integer in 1..MaxQuantity. pos is the
415	// record's 1-based position in the batches array.
416	//
417	// The structural rules (member names, strict string decoding, quantity
418	// range) are shared with parseManifestRecord; only this source's reporting
419	// differs: problems are surfaced as *FormatError with registry wording, a
420	// duplicated member anywhere in the object outranks an unknown one, and
421	// text values are read verbatim — validate handles the empty-string case.
422	func parseRegistryRecord(raw json.RawMessage, pos int) (Batch, error) {
423		var b Batch
424		fields, err := parseObjectFields(raw)
425		if err != nil {
426			return b, &FormatError{Position: pos, Reason: "record must be a JSON object holding exactly \"batch\", \"product\", \"quantity\" and \"unit\""}
427		}
428		// The batch id is attached to errors only when it is unambiguous:
429		// exactly one "batch" member carrying a JSON string whose decoded text
430		// is valid UTF-8. When the "batch" member itself is duplicated, or its
431		// bytes are not valid UTF-8, no id (and never a U+FFFD replacement) is
432		// picked arbitrarily.
433		batchID := unambiguousBatchID(fields, textVerbatim)
434		fail := func(field, reason string) (Batch, error) {
435			return Batch{}, &FormatError{Position: pos, Batch: batchID, Field: field, Reason: reason}
436		}
437	
438		switch fault := checkRecordMembers(fields, true); fault.kind {
439		case faultDuplicate:
440			return fail(fault.field, "field appears more than once; duplicate fields are not allowed")
441		case faultUnknown:
442			return fail(fault.field, "unknown field; only \"batch\", \"product\", \"quantity\" and \"unit\" are allowed")
443		}
444	
445		text := func(name string) (string, error) {
446			rawValue, ok := findField(fields, name)
447			value, problem, _ := decodeRecordText(rawValue, ok, textVerbatim)
448			switch problem {
449			case fieldMissing:
450				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "required field is missing"}
451			case fieldEncoding:
452				return "", &FormatError{Position: pos, Batch: batchID, Field: name,
453					Reason: "must be valid UTF-8 text: malformed bytes or lone surrogate escapes are rejected instead of being replaced with U+FFFD"}
454			case fieldNotString:
455				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
456			}
457			return value, nil
458		}
459		if b.Batch, err = text("batch"); err != nil {
460			return Batch{}, err
461		}
462		if b.Product, err = text("product"); err != nil {
463			return Batch{}, err
464		}
465		if b.Unit, err = text("unit"); err != nil {
466			return Batch{}, err
467		}
468		quantityRaw, ok := findField(fields, "quantity")
469		if !ok {
470			return fail("quantity", "required field is missing")
471		}
472		b.Quantity, err = registryQuantityError(bytes.TrimSpace(quantityRaw))
473		if err != nil {
474			return fail("quantity", err.Error())
475		}
476		return b, nil
477	}
478	
479	// isJSONInteger reports whether token is a JSON number literal without
480	// fraction or exponent. The token comes from validated JSON, so leading
481	// zeros cannot hide extra digits.
482	func isJSONInteger(token string) bool {
483		if token == "" {
484			return false
485		}
486		if token[0] == '-' {
487			token = token[1:]
488		}
489		if token == "" {
490			return false
491		}
492		for i := 0; i < len(token); i++ {
493			if token[i] < '0' || token[i] > '9' {
494				return false
495			}
496		}
497		return true
498	}
499	
500	// objectField is one member of a JSON object in source order; the key is
501	// the decoded JSON string, so escaped spellings compare by meaning.
502	type objectField struct {
503		key   string
504		value json.RawMessage
505	}
506	
507	// parseObjectFields decodes a single JSON object value into its members in
508	// source order, keeping duplicates visible for the caller to reject. Keys
509	// are re-scanned strictly: encoding/json would otherwise hand back U+FFFD
510	// substitutions for malformed key bytes.
511	func parseObjectFields(raw []byte) ([]objectField, error) {
512		trimmed := bytes.TrimSpace(raw)
513		if len(trimmed) == 0 || trimmed[0] != '{' {
514			return nil, errors.New("value is not a JSON object")
515		}
516		dec := json.NewDecoder(bytes.NewReader(trimmed))
517		if _, err := dec.Token(); err != nil { // opening brace
518			return nil, err
519		}
520		var fields []objectField
521		for dec.More() {
522			keyStart := dec.InputOffset()
523			tok, err := dec.Token()
524			keyEnd := dec.InputOffset()
525			if err != nil {
526				return nil, err
527			}
528			key, ok := tok.(string)
529			if !ok {
530				return nil, errors.New("object keys must be JSON strings")
531			}
532			if _, err := unmarshalStringStrict(keyTokenBytes(trimmed, int(keyStart), int(keyEnd))); err != nil {
533				if errors.Is(err, errStringEncoding) {
534					return nil, errors.New("object key contains bytes that are not valid UTF-8")
535				}
536				return nil, err
537			}
538			var value json.RawMessage
539			if err := dec.Decode(&value); err != nil {
540				return nil, err
541			}
542			fields = append(fields, objectField{key: key, value: value})
543		}
544		if _, err := dec.Token(); err != nil { // closing brace
545			return nil, err
546		}
547		return fields, nil
548	}
549	
550	// trimJSONSpace strips only the four JSON whitespace bytes (space, tab,
551	// carriage return, newline). bytes.TrimSpace would also remove U+000B and
552	// other Unicode whitespace, which is illegal around a JSON token and must
553	// therefore be rejected rather than ignored.
554	func trimJSONSpace(b []byte) []byte {
555		isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\n' }
556		for len(b) > 0 && isSpace(b[0]) {
557			b = b[1:]
558		}
559		for len(b) > 0 && isSpace(b[len(b)-1]) {
560			b = b[:len(b)-1]
561		}
562		return b
563	}
564	
565	// keyTokenBytes isolates one key token inside trimmed[start:end]. The
566	// decoder reports the offset just after the preceding token (so the span
567	// may still contain a separating comma and whitespace), hence the left trim.
568	func keyTokenBytes(trimmed []byte, start, end int) []byte {
569		return bytes.TrimLeft(trimmed[start:end], " \t\r\n,")
570	}
571	
572	// duplicateField returns the first field name appearing more than once.
573	func duplicateField(fields []objectField) (string, bool) {
574		seen := make(map[string]struct{}, len(fields))
575		for _, f := range fields {
576			if _, dup := seen[f.key]; dup {
577				return f.key, true
578			}
579			seen[f.key] = struct{}{}
580		}
581		return "", false
582	}
583	
584	// findField returns the raw value of the first member named name.
585	func findField(fields []objectField, name string) (json.RawMessage, bool) {
586		for _, f := range fields {
587			if f.key == name {
588				return f.value, true
589			}
590		}
591		return nil, false
592	}
593	
594	// countField counts the members named name.
595	func countField(fields []objectField, name string) int {
596		n := 0
597		for _, f := range fields {
598			if f.key == name {
599				n++
600			}
601		}
602		return n
603	}
604	
605	func validate(reg *Registry) error {
606		seen := make(map[string]int, len(reg.Batches))
607		for i, b := range reg.Batches {
608			pos := i + 1
609			if b.Batch == "" || b.Product == "" || b.Unit == "" {
610				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
611			}
612			if b.Quantity <= 0 {
613				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
614			}
615			if first, dup := seen[b.Batch]; dup {
616				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
617			}
618			seen[b.Batch] = pos
619		}
620		return nil
621	}
