623	// ManifestRecordError reports a manifest record that is structurally invalid
624	// or carries a quantity outside the accepted range. Position is the record's
625	// 1-based position in the manifest.
626	type ManifestRecordError struct {
627		Position int
628		Batch    string // normalized batch id when available, otherwise ""
629		Reason   string
630	}
631	
632	func (e *ManifestRecordError) Error() string {
633		if e.Batch != "" {
634			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
635		}
636		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
637	}
